cd /workspace; sed -i "s#'../../DirectionalTransition'#'@/app/DirectionalTransition'#" "app/product/[slug]/page.tsx"; cat >> app/globals.css <<'EOF'

/* Snapshots don't include the card's overflow clipping, so round the
   thumbnail itself to keep the morph from flashing square corners. */
.product-card .product-image {
  border-radius: 12px 12px 0 0;
}

/* ---------- View transitions ---------- */

:root {
  --duration-exit: 150ms;
  --duration-enter: 210ms;
  --duration-move: 400ms;
}

/* Let clicks reach the live page while a transition runs. */
::view-transition {
  pointer-events: none;
}

/* Shared element: grid thumbnail <-> detail hero */
::view-transition-group(.morph) {
  animation-duration: var(--duration-move);
}

::view-transition-image-pair(.morph) {
  animation-name: via-blur;
}

@keyframes via-blur {
  30% {
    filter: blur(3px);
  }
}

/* Suspense reveal: skeleton out, content in */
::view-transition-old(.slide-down) {
  animation:
    var(--duration-exit) ease-out both fade reverse,
    var(--duration-exit) ease-out both slide-y reverse;
}

::view-transition-new(.slide-up) {
  animation:
    var(--duration-enter) ease-in var(--duration-exit) both fade,
    var(--duration-move) ease-in both slide-y;
}

/* Directional page navigation */
::view-transition-old(.nav-forward) {
  --slide-offset: -60px;
  animation:
    var(--duration-exit) ease-in both fade reverse,
    var(--duration-move) ease-in-out both slide reverse;
}

::view-transition-new(.nav-forward) {
  --slide-offset: 60px;
  animation:
    var(--duration-enter) ease-out var(--duration-exit) both fade,
    var(--duration-move) ease-in-out both slide;
}

::view-transition-old(.nav-back) {
  --slide-offset: 60px;
  animation:
    var(--duration-exit) ease-in both fade reverse,
    var(--duration-move) ease-in-out both slide reverse;
}

::view-transition-new(.nav-back) {
  --slide-offset: -60px;
  animation:
    var(--duration-enter) ease-out var(--duration-exit) both fade,
    var(--duration-move) ease-in-out both slide;
}

@keyframes fade {
  from {
    filter: blur(3px);
    opacity: 0;
  }
  to {
    filter: blur(0);
    opacity: 1;
  }
}

@keyframes slide-y {
  from {
    transform: translateY(10px);
  }
  to {
    transform: translateY(0);
  }
}

@keyframes slide {
  from {
    translate: var(--slide-offset);
  }
  to {
    translate: 0;
  }
}

/* Reduced motion: swap content instantly, no movement or fades. */
@media (prefers-reduced-motion: reduce) {
  ::view-transition-group(*),
  ::view-transition-image-pair(*),
  ::view-transition-old(*),
  ::view-transition-new(*) {
    animation-duration: 0s !important;
    animation-delay: 0s !important;
  }

  .skeleton-image,
  .skeleton-text {
    animation: none;
  }
}
EOF
npx tsc --noEmit && npm run build 2>&1 | tail -25

(npx next start -p 3123 > /tmp/next.log 2>&1 &) ; sleep 4; cat > /tmp/pw/test.mjs <<'EOF'
import { chromium } from 'playwright'
const reduced = process.argv[2] === 'reduce'
const browser = await chromium.launch()
const page = await browser.newPage({ reducedMotion: reduced ? 'reduce' : 'no-preference' })
await page.addInitScript(() => {
  window.__vt = []
  const orig = document.startViewTransition.bind(document)
  document.startViewTransition = (arg) => {
    const t = orig(arg)
    const rec = { types: arg && arg.types ? [...arg.types] : [] , anims: [] }
    window.__vt.push(rec)
    t.ready.then(() => {
      rec.anims = document.getAnimations().map(a => {
        const e = a.effect
        return `${e.pseudoElement} ${a.animationName || ''} ${e.getComputedTiming().duration}ms`
      })
      rec.classes = [...document.querySelectorAll('*')].map(el => {
        const s = getComputedStyle(el)
        return s.viewTransitionName !== 'none' ? `${el.tagName}.${el.className} name=${s.viewTransitionName} class=${s.viewTransitionClass}` : null
      }).filter(Boolean)
    })
    return t
  }
})
await page.goto('http://localhost:3123/')
await page.waitForTimeout(1000)
await page.click('a[href="/product/leather-backpack"]')
await page.waitForURL('**/product/leather-backpack')
await page.waitForSelector('.product-price')
await page.waitForTimeout(1000)
await page.click('a.back-link')
await page.waitForURL('http://localhost:3123/')
await page.waitForTimeout(1000)
console.log(JSON.stringify(await page.evaluate(() => window.__vt), null, 1))
await browser.close()
EOF
cd /tmp/pw && node test.mjs
